def sender_key(purpose, sender, recipient):
    if purpose == 'privacy':
        return recipient + "'s public key"
    return sender + "'s private key"

def receiver_key(purpose, sender, recipient):
    if purpose == 'privacy':
        return recipient + "'s private key"
    return sender + "'s public key"

def factors(methods):
    kind = {'password':'know','pin':'know','security question':'know','token':'hold','smart card':'hold','phone':'hold','fingerprint':'are','face':'are','iris':'are','voice':'are'}
    return len({kind[m] for m in methods})
